## Code Example

```javascript
// Express.js-like audit middleware sketch
app.use((req, res, next) => {
  const event = {
    action: req.method + ' ' + req.path,
    user_id: req.user?.id,
    resource: req.path,
    timestamp: Date.now(),
    correlation_id: req.headers['x-correlation-id'] || generateId(),
    payload_size: JSON.stringify(req.body || {}).length
  };
  if (event.user_id) event.user_id = anonymize(event.user_id);
  // pseudo producers
  auditKafkaProducer.send({ topic: 'audit', value: JSON.stringify(event) });
  auditPostgresClient.insert('audit', event);
  next();
});
```

